int main() {
    int n, k, l, c, d, p, nl, np;
    cin >> n >> k >> l >> c >> d >> p >> nl >> np;

    // Total milliliters of drink
    long long total_drink = (long long)k * l;
    // Total slices of lime
    long long total_lime = (long long)c * d;
    // Total grams of salt
    long long total_salt = p;

    // Number of toasts possible based on each resource
    long long toasts_drink = total_drink / nl;
    long long toasts_lime = total_lime / 1; // each toast needs 1 slice
    long long toasts_salt = total_salt / np;

    // Total toasts that can be made
    long long total_toasts = min({toasts_drink, toasts_lime, toasts_salt});

    // Each friend makes the same number of toasts
    long long toasts_per_friend = total_toasts / n;

    cout << toasts_per_friend << endl;

    return 0;
}
